import json, math
from fractions import Fraction as F
from pathlib import Path
bank=[]
def topic(grade,subject,title,ref,fn):
    tid=f'{grade}-{sum(t["grade"]==grade for t in bank)+1:02}'
    tasks=[]
    for n in (1,2,3):
        prompt,answer,solution=fn(n)
        a=F(answer).limit_denominator(1000000)
        display=str(a) if a.denominator!=1 else str(a.numerator)
        tasks.append(dict(id=f'{tid}-{n}',prompt=prompt,answer=float(a),display=display,solution=solution))
    
    if grade<=6:
        subject='Наглядная геометрия' if subject=='Геометрия' or tid=='6-07' else 'Текстовые задачи' if tid=='5-05' else 'Числа и вычисления'
    bank.append(dict(id=tid,grade=grade,course='Математика' if grade<=6 else subject,subject=subject,title=title,ref=ref,tasks=tasks))

M='Математика'; A='Алгебра'; G='Геометрия'; P='Вероятность и статистика'; H='Алгебра и начала математического анализа'
topic(5,M,'Порядок действий','14',lambda n:(f'Вычислите: {20+n} + {n+2} · (18 − 12).',20+n+(n+2)*6,f'Сначала скобки: 18 − 12 = 6. Затем умножение: {n+2} · 6 = {(n+2)*6}. Прибавляем {20+n}.'))
topic(5,M,'Деление с остатком','14',lambda n:(f'Найдите остаток от деления {7*(n+4)+3} на 7.',3,f'{7*(n+4)+3} = 7 · {n+4} + 3. Остаток 3 меньше делителя 7.'))
topic(5,M,'Обыкновенные дроби','14',lambda n:(f'Вычислите: {n}/8 + {n+1}/8. Ответ можно записать дробью.',F(2*n+1,8),f'При одинаковых знаменателях складываем числители: ({n} + {n+1})/8 = {2*n+1}/8.'))
topic(5,M,'Десятичные дроби','14',lambda n:(f'Вычислите: {n},25 + 2,5.',F(n)+F(11,4),f'Запишем 2,5 как 2,50. Складываем по разрядам: {n},25 + 2,50 = {n+2},75.'))
topic(5,M,'Скорость, время, расстояние','15',lambda n:(f'Велосипедист ехал {n+1} ч со скоростью 12 км/ч. Какое расстояние он проехал? Ответ в километрах.',12*(n+1),f'Расстояние равно скорости, умноженной на время: 12 · {n+1} = {12*(n+1)} км.'))
topic(5,G,'Периметр прямоугольника','15',lambda n:(f'Стороны прямоугольника равны {n+4} см и {n+2} см. Найдите периметр в сантиметрах.',4*n+12,f'P = 2(a + b) = 2 · ({n+4} + {n+2}) = {4*n+12} см.'))
topic(5,G,'Площадь прямоугольника','15',lambda n:(f'Прямоугольник имеет длину {n+5} см и ширину 4 см. Найдите площадь в см².',4*(n+5),f'S = a · b = {n+5} · 4 = {4*(n+5)} см².'))
topic(5,G,'Объём прямоугольного параллелепипеда','15',lambda n:(f'Длина коробки {n+3} см, ширина 3 см, высота 2 см. Найдите её объём в см³.',6*(n+3),f'V = a · b · c = {n+3} · 3 · 2 = {6*(n+3)} см³.'))

topic(6,M,'НОД и НОК','15',lambda n:(f'Найдите наибольший общий делитель чисел {6*(n+1)} и {9*(n+1)}.',3*(n+1),f'{6*(n+1)} = {3*(n+1)} · 2, а {9*(n+1)} = {3*(n+1)} · 3. Числа 2 и 3 взаимно просты, поэтому НОД равен {3*(n+1)}.'))
topic(6,M,'Действия с дробями','16',lambda n:(f'Вычислите: {n}/4 + 1/6. Ответ можно записать дробью.',F(3*n+2,12),f'Общий знаменатель 12: {n}/4 = {3*n}/12, 1/6 = 2/12. Сумма равна {3*n+2}/12.'))
topic(6,M,'Проценты','16',lambda n:(f'В книге {100+40*n} страниц. Прочитано 25% книги. Сколько страниц прочитано?',25+10*n,f'25% = 1/4. Поэтому {100+40*n} : 4 = {25+10*n} страниц.'))
topic(6,M,'Отношения и пропорции','16',lambda n:(f'Разделите {30*n} в отношении 2 : 3. Найдите меньшую часть.',12*n,f'Всего 2 + 3 = 5 долей. Меньшая часть: {30*n} : 5 · 2 = {12*n}.'))
topic(6,M,'Положительные и отрицательные числа','16',lambda n:(f'Вычислите: −{7*n} + {3*n} − 2.',-4*n-2,f'−{7*n} + {3*n} = −{4*n}. Ещё вычитаем 2 и получаем −{4*n+2}.'))
topic(6,M,'Модуль числа','16',lambda n:(f'Вычислите: |−{n+5}| − |{n+1}|.',4,f'Модуль — расстояние до нуля. Получаем {n+5} − {n+1} = 4.'))
topic(6,M,'Координатная плоскость','16',lambda n:(f'Точка A имеет координаты (−{n+2}; {n+4}). Чему равна её абсцисса?',-(n+2),f'Абсцисса — первая координата точки, то есть −{n+2}.'))
topic(6,G,'Осевая симметрия','17',lambda n:(f'Точка A({n+1}; {3*n}) отражена относительно оси абсцисс. Найдите ординату полученной точки.',-3*n,f'При отражении относительно оси x абсцисса сохраняется, а ордината меняет знак: ({n+1}; −{3*n}).'))

topic(7,A,'Линейные уравнения','42',lambda n:(f'Решите уравнение: 3x + {n+2} = {4*n+8}.',n+2,f'3x = {4*n+8} − {n+2} = {3*n+6}. Делим обе части на 3: x = {n+2}.'))
topic(7,A,'Степени с натуральным показателем','41–42',lambda n:(f'Вычислите: 2^{n+2} · 2².',2**(n+4),f'При умножении степеней одного основания показатели складываются: 2^({n+2}+2) = 2^{n+4} = {2**(n+4)}.'))
topic(7,A,'Многочлены и формулы сокращённого умножения','42',lambda n:(f'Найдите значение выражения (x + 3)² − x² при x = {n+1}.',6*(n+1)+9,f'(x + 3)² − x² = 6x + 9. Подставляем x = {n+1}: {6*(n+1)+9}.'))
topic(7,A,'Линейная функция','42',lambda n:(f'Функция задана формулой y = 3x − 2. Найдите y при x = {n+2}.',3*n+4,f'Подставим значение x: y = 3 · {n+2} − 2 = {3*n+4}.'))
topic(7,A,'Системы линейных уравнений','42',lambda n:(f'В системе x + y = {2*n+5}, x − y = 3 найдите x.',n+4,f'Сложим уравнения: 2x = {2*n+8}. Значит, x = {n+4}.'))
topic(7,G,'Смежные и вертикальные углы','70',lambda n:(f'Один из двух смежных углов равен {40+10*n}°. Найдите второй угол в градусах.',140-10*n,f'Сумма смежных углов равна 180°. Второй угол: 180° − {40+10*n}° = {140-10*n}°.'))
topic(7,G,'Углы треугольника','71',lambda n:(f'В равнобедренном треугольнике угол при вершине равен {40+20*n}°. Найдите угол при основании в градусах.',70-10*n,f'Углы при основании равны. Каждый равен (180° − {40+20*n}°) : 2 = {70-10*n}°.'))
topic(7,P,'Среднее, медиана и размах','92',lambda n:(f'Найдите среднее арифметическое чисел {n+2}, {n+4} и {n+9}.',n+5,f'Сумма равна {3*n+15}. Делим на число значений: {3*n+15} : 3 = {n+5}.'))
topic(7,P,'Частота случайного события','92',lambda n:(f'В {20*n} бросках монеты орёл выпал {8*n} раз. Найдите относительную частоту выпадения орла.',F(2,5),f'Относительная частота = число появлений события / число опытов: {8*n}/{20*n} = 2/5 = 0,4.'))

topic(8,A,'Квадратные корни','42',lambda n:(f'Вычислите: √{(n+5)**2} + √{(n+2)**2}.',2*n+7,f'Арифметические квадратные корни неотрицательны: √{(n+5)**2} = {n+5}, √{(n+2)**2} = {n+2}. Сумма {2*n+7}.'))
topic(8,A,'Квадратные уравнения','43',lambda n:(f'Найдите больший корень уравнения x² − {2*n+4}x + {n*(n+4)} = 0.',n+4,f'Разложение: (x − {n})(x − {n+4}) = 0. Корни {n} и {n+4}; больший — {n+4}.'))
topic(8,A,'Рациональные выражения','42',lambda n:(f'Найдите значение (x² − 9)/(x − 3) при x = {n+4}.',n+7,f'x ≠ 3. Сокращаем (x − 3)(x + 3)/(x − 3) = x + 3. При x = {n+4} получаем {n+7}.'))
topic(8,A,'Линейные неравенства','43',lambda n:(f'Найдите наименьшее целое решение неравенства 2x > {4*n+2}.',2*n+2,f'Делим на положительное число 2: x > {2*n+1}. Наименьшее подходящее целое — {2*n+2}.'))
topic(8,G,'Теорема Пифагора','71',lambda n:(f'Катеты прямоугольного треугольника равны {3*n} см и {4*n} см. Найдите гипотенузу в сантиметрах.',5*n,f'c² = ({3*n})² + ({4*n})² = {25*n*n}. Значит, c = {5*n} см.'))
topic(8,G,'Площади четырёхугольников','71',lambda n:(f'Основания трапеции равны {n+3} см и {n+7} см, высота — 4 см. Найдите площадь в см².',4*n+20,f'S = (a + b) · h / 2 = ({n+3} + {n+7}) · 4 / 2 = {4*n+20} см².'))
topic(8,G,'Подобие треугольников','71',lambda n:(f'Сторона первого треугольника равна {n+3} см, соответствующая сторона подобного ему второго — {2*(n+3)} см. Площадь первого равна {5*n} см². Найдите площадь второго в см².',20*n,f'Коэффициент подобия второго к первому равен 2. Площади относятся как 2² = 4. Площадь второго: {5*n} · 4 = {20*n} см².'))
topic(8,P,'Вероятность противоположного события','93',lambda n:(f'Вероятность дождя завтра равна 0,{n+1}. Какова вероятность того, что дождя не будет?',F(9-n,10),f'Вероятности противоположных событий в сумме дают 1: 1 − 0,{n+1} = 0,{9-n}.'))
topic(8,P,'Дисперсия числового набора','93',lambda n:(f'Найдите дисперсию набора {n}, {n+2}, {n+4}. Используйте среднее квадратов отклонений (деление на 3).',F(8,3),f'Среднее равно {n+2}. Отклонения: −2, 0, 2. Дисперсия: (4 + 0 + 4)/3 = 8/3.'))

topic(9,A,'Арифметическая прогрессия','44',lambda n:(f'В арифметической прогрессии a₁ = {n+2}, d = 3. Найдите a₆.',n+17,f'a₆ = a₁ + 5d = {n+2} + 5 · 3 = {n+17}.'))
topic(9,A,'Геометрическая прогрессия','44',lambda n:(f'В геометрической прогрессии b₁ = {n+1}, q = 2. Найдите b₅.',16*(n+1),f'b₅ = b₁ · q⁴ = {n+1} · 16 = {16*(n+1)}.'))
topic(9,A,'Квадратичная функция','44',lambda n:(f'Найдите абсциссу вершины параболы y = x² − {2*(n+1)}x + 5.',n+1,f'Абсцисса вершины x₀ = −b/(2a) = {2*(n+1)}/2 = {n+1}.'))
topic(9,A,'Биквадратные уравнения','43',lambda n:(f'Найдите наибольший корень уравнения x⁴ − {1+(n+1)**2}x² + {(n+1)**2} = 0.',n+1,f'Пусть t = x². Тогда (t − 1)(t − {(n+1)**2}) = 0. Получаем x = ±1 и x = ±{n+1}. Наибольший корень {n+1}.'))
topic(9,G,'Векторы на плоскости','72',lambda n:(f'Векторы a = ({n}; 2) и b = (3; −1). Найдите их скалярное произведение.',3*n-2,f'a · b = {n} · 3 + 2 · (−1) = {3*n-2}.'))
topic(9,G,'Окружность и круг','72',lambda n:(f'Радиус круга равен {n+2} см. Его площадь равна kπ см². Найдите k.',(n+2)**2,f'S = πr² = {(n+2)**2}π см². Поэтому k = {(n+2)**2}.'))
topic(9,G,'Теорема косинусов','72',lambda n:(f'Две стороны треугольника равны {3*n} см и {5*n} см, угол между ними равен 60°. Найдите квадрат длины третьей стороны в см².',19*n*n,f'c² = a² + b² − 2ab · cos 60°. Так как cos 60° = 1/2, c² = {9*n*n} + {25*n*n} − {15*n*n} = {19*n*n}.'))
topic(9,P,'Комбинаторика: сочетания','93',lambda n:(f'Из {n+4} учеников нужно выбрать двух дежурных. Порядок не важен. Сколько пар можно выбрать?',math.comb(n+4,2),f'C({n+4}, 2) = {n+4} · {n+3} / 2 = {math.comb(n+4,2)}.'))
topic(9,P,'Испытания Бернулли','93',lambda n:(f'Правильную монету подбрасывают {n+1} раза. Броски независимы. Какова вероятность того, что орёл выпадет ровно один раз?',F(n+1,2**(n+1)),f'Есть {n+1} способов выбрать бросок с орлом. Вероятность каждой последовательности 1/{2**(n+1)}. Итого {n+1}/{2**(n+1)}.'))

topic(10,H,'Корни натуральной степени','15',lambda n:(f'Найдите арифметический кубический корень из {(n+2)**3}.',n+2,f'({n+2})³ = {(n+2)**3}, поэтому корень равен {n+2}.'))
topic(10,H,'Тригонометрические выражения','15',lambda n:(f'Вычислите: {2*n} · sin 30° + 2 · cos 60°.',n+1,f'sin 30° = cos 60° = 1/2. Получаем {2*n} · 1/2 + 2 · 1/2 = {n+1}.'))
topic(10,H,'Тригонометрические уравнения','15',lambda n:(f'Найдите наименьший положительный корень уравнения sin({n}x) = 0. Ответ укажите в градусах.',180//n,f'sin α = 0 при α = 180° · k, где k — целое. Поэтому x = 180° · k/{n}, наименьшее положительное значение — {180//n}°.'))
topic(10,H,'Бесконечно убывающая прогрессия','16',lambda n:(f'Найдите сумму бесконечно убывающей геометрической прогрессии с первым членом {n+2} и знаменателем 1/2.',2*(n+2),f'|q| < 1, поэтому S = b₁/(1 − q) = {n+2}/(1 − 1/2) = {2*(n+2)}.'))
topic(10,G,'Расстояние от точки до плоскости','32',lambda n:(f'Из точки A проведены перпендикуляр AH к плоскости и наклонная AB. Известно: AB = {5*n} см, HB = {4*n} см. Найдите расстояние от A до плоскости в сантиметрах.',3*n,f'AH перпендикулярен HB. По теореме Пифагора AH = √(({5*n})² − ({4*n})²) = {3*n} см.'))
topic(10,G,'Призма','32–33',lambda n:(f'Площадь основания прямой призмы равна {6*n} см², высота — 5 см. Найдите объём в см³.',30*n,f'V = S основания · h = {6*n} · 5 = {30*n} см³.'))
topic(10,G,'Пирамида','32–33',lambda n:(f'Площадь основания пирамиды равна {12*n} см², высота — 6 см. Найдите объём в см³.',24*n,f'V = S основания · h / 3 = {12*n} · 6 / 3 = {24*n} см³.'))
topic(10,P,'Независимые события','57',lambda n:(f'События A и B независимы. P(A) = 0,{n+1}, P(B) = 0,5. Найдите вероятность их одновременного наступления.',F(n+1,20),f'Для независимых событий P(A ∩ B) = P(A) · P(B) = 0,{n+1} · 0,5 = {F(n+1,20)}.'))
topic(10,P,'Комбинаторное правило умножения','57',lambda n:(f'В меню {n+2} салата, 4 горячих блюда и 2 напитка. Сколько обедов можно составить, выбирая по одному блюду каждого вида?',8*(n+2),f'По правилу умножения: {n+2} · 4 · 2 = {8*(n+2)} вариантов.'))

topic(11,H,'Логарифмы','16',lambda n:(f'Вычислите log₂({2**(n+2)}).',n+2,f'Логарифм — показатель степени: 2^{n+2} = {2**(n+2)}. Ответ {n+2}.'))
topic(11,H,'Показательные уравнения','16',lambda n:(f'Решите уравнение 3ˣ = {3**(n+1)}.',n+1,f'{3**(n+1)} = 3^{n+1}. Поскольку функция 3ˣ строго возрастает, равенство выполняется только при x = {n+1}.'))
topic(11,H,'Производная','16–17',lambda n:(f'Дана функция f(x) = x³ − 2x. Найдите f′({n}).',3*n*n-2,f'f′(x) = 3x² − 2. Поэтому f′({n}) = 3 · {n}² − 2 = {3*n*n-2}.'))
topic(11,H,'Наименьшее значение функции','16–17',lambda n:(f'Найдите наименьшее значение f(x) = x² − {2*(n+1)}x + {(n+1)**2+3} на отрезке [0; {2*(n+1)}].',3,f'f(x) = (x − {n+1})² + 3. Вершина x = {n+1} лежит на отрезке; квадрат обращается в ноль, минимум равен 3.'))
topic(11,G,'Цилиндр','33',lambda n:(f'Радиус цилиндра равен {n+1} см, высота — 5 см. Объём равен kπ см³. Найдите k.',5*(n+1)**2,f'V = πr²h = π · {n+1}² · 5 = {5*(n+1)**2}π см³.'))
topic(11,G,'Конус','33',lambda n:(f'Радиус основания конуса равен {n+1} см, высота — 6 см. Объём равен kπ см³. Найдите k.',2*(n+1)**2,f'V = πr²h/3 = π · {n+1}² · 6/3 = {2*(n+1)**2}π см³.'))
topic(11,G,'Векторы в пространстве','33–34',lambda n:(f'Векторы a = ({n}; 2; −1) и b = (3; 0; 4). Найдите их скалярное произведение.',3*n-4,f'a · b = {n} · 3 + 2 · 0 + (−1) · 4 = {3*n-4}.'))
topic(11,P,'Математическое ожидание','57',lambda n:(f'Случайная величина X принимает значение 0 с вероятностью 0,5 и значение {2*(n+1)} с вероятностью 0,5. Найдите E(X).',n+1,f'E(X) = 0 · 0,5 + {2*(n+1)} · 0,5 = {n+1}.'))
topic(11,P,'Дисперсия биномиального распределения','57',lambda n:(f'Число успехов X в {4*n} независимых испытаниях имеет биномиальное распределение. Вероятность успеха в каждом испытании равна 0,5. Найдите D(X).',n,f'D(X) = np(1 − p) = {4*n} · 0,5 · 0,5 = {n}.'))

